//! Synthetic public states only. Expected payments, counters and PS2 bytes
//! are supplied explicitly, never generated by the verifier or a planner.
//! No program dispatch, exporter, key material, signature, RPC or transaction.
#![cfg(feature = "wide-economy-experimental")]

use frontier_abi::addr::{defence_claim_seed, keeper_tag8, AddrCtx};
use frontier_abi::bytes::*;
use frontier_abi::layout::{
    beacon::{bell_anchor as BA, defence_claim as DC},
    world::{defence_pool as DP, season as S},
};
use frontier_abi::v2::presets::{PROGRAM_VERSION_S1, RULESET_HASH_V3};
use frontier_abi::world_index::{
    arrival::{arrival_slot_address, wide_arrival_slot as AS, WideArrivalSlot},
    rules::wide_region,
    ProvinceKey, WideCoord, WideHostRef, WorldId,
};
use permutation_rules::hash::sha256;
use verify_core::wide_defence::{self as v, Account, Clock, Refusal, Rent, Transition};

const PROGRAM: [u8; 32] = [0x42; 32];
const KEEPER: [u8; 32] = [0x33; 32];
const ID: u64 = 7;
const GENESIS: i64 = 1_000;
const FLOOR: u64 = 384; // (128 + 256) * 1, threshold 1.0

#[derive(Clone)]
struct Case {
    instruction: Vec<u8>,
    clock: Clock,
    rent: Rent,
    before: Vec<Account>,
    after: Vec<Account>,
    record: Vec<u8>,
}
fn image(key: [u8; 32], data: Vec<u8>, lamports: u64, writable: bool) -> Account {
    Account {
        key,
        owner: PROGRAM,
        executable: false,
        rent_epoch: 9,
        is_signer: false,
        is_writable: writable,
        lamports,
        data,
    }
}
fn header(magic: [u8; 8], size: usize) -> Vec<u8> {
    let mut d = vec![0; size];
    assert!(wr_arr(&mut d, 0, &magic));
    assert!(wr_u64(&mut d, 8, ID));
    d
}
impl Case {
    fn new(n: u8) -> Self {
        // Public PDA hash only. The checker mirrors the handler's stored-bump
        // hash check; neither asserts a signature nor proves off-curve history.
        let season = sha256(&[
            b"season",
            &ID.to_le_bytes(),
            &[253],
            &PROGRAM,
            b"ProgramDerivedAddress",
        ]);
        let ctx = AddrCtx {
            season,
            program: PROGRAM,
        };
        let world = WorldId::derive_legacy_season(&season, &PROGRAM).unwrap();
        let coord = WideCoord::checked(150, 0).unwrap();
        let dest = ProvinceKey::new(world, coord);
        let region = wide_region(coord);
        let mut sd = header(S::MAGIC, S::SIZE);
        sd[S::BUMP] = 253;
        sd[S::STATUS] = S::STATUS_SEEDED;
        wr_i64(&mut sd, S::GENESIS_TS, GENESIS);
        wr_u32(&mut sd, S::END_BELL, 1000);
        wr_arr(&mut sd, S::RULESET_HASH, &RULESET_HASH_V3);
        wr_u16(&mut sd, S::PROGRAM_VERSION, PROGRAM_VERSION_S1 | 0x4000);
        wr_u32(&mut sd, S::WINDOW_FROM_BELL, u32::MAX);
        wr_u32(&mut sd, S::REVEAL_WINDOW, 600);
        wr_u32(&mut sd, S::DEFENCE_CAP_MILLI, 1000);
        sd[S::LATENESS_SLOTS] = 5;
        let mut pd = header(DP::MAGIC, DP::SIZE);
        wr_u64(&mut pd, DP::PER_BELL_REGION_CAP, 17);
        wr_u64(&mut pd, DP::PER_KEEPER_DAY_CAP, 25);
        pd[DP::RSV] = 0xa7; // legacy headers do not reject reserved bytes
        let mut cd = header(DC::MAGIC, DC::SIZE);
        wr_arr(&mut cd, DC::BENEFICIARY, &KEEPER);
        cd[DC::RSV] = 0xb6;
        let mut keeper = image(KEEPER, vec![], 100, true);
        keeper.owner = [0; 32];
        keeper.is_signer = true;
        let mut system = image([0; 32], vec![], 1, false);
        system.owner = [0x99; 32];
        system.executable = true;
        let mut before = vec![
            keeper,
            image(season, sd, 1000, false),
            image(ctx.defence_pool(), pd, FLOOR + 1000, true),
            image(
                ctx.of(&defence_claim_seed(&keeper_tag8(&KEEPER), 0)),
                cd,
                256,
                true,
            ),
            system,
        ];
        let mut ad = header(BA::MAGIC, BA::SIZE);
        wr_u32(&mut ad, BA::BELL, 10);
        ad[BA::REGION] = region;
        wr_i64(&mut ad, BA::A, GENESIS + 6000);
        wr_u64(&mut ad, BA::SLOT, 100);
        let anchor = image(ctx.bell_anchor(10, region), ad, 33, false);
        for k in 0..n {
            let slot = WideArrivalSlot {
                season_id: ID,
                dest,
                bell: 10,
                faction: k / 4,
                i: k % 4,
                transit_slot: 0,
                host: WideHostRef::new(dest, 0, 2, 1).unwrap(),
                citizen: [0x46; 32],
                unit: 0,
                stance: 0,
                tile: 0,
                retreat_bps: 0,
                dealt_bps: 10_000,
                dep_mass: 100_000,
                flags: 0,
                beneficiary: KEEPER,
                rent_to: [0x55; 32],
                ev_slot: 105,
                ev_price: 1_000_000,
                ev_limit: 100_000,
                ev_loaded: 100_000,
                claimed: false,
            };
            let mut data = vec![0; AS::SIZE];
            slot.write(&mut data).unwrap();
            before.push(image(
                arrival_slot_address(&ctx, dest, 10, slot.faction, slot.i),
                data,
                77,
                true,
            ));
            before.push(anchor.clone());
        }
        let mut out = Self {
            // Exact independently literal envelope, not a planner output.
            instruction: vec![0xdc, 0xff, 1, 6, 0, 0, 0, 0, n],
            clock: Clock {
                slot: 200,
                epoch_start_timestamp: 0,
                epoch: 1,
                leader_schedule_epoch: 1,
                unix_timestamp: GENESIS + 6600,
            },
            rent: Rent {
                lamports_per_byte: 1,
                exemption_threshold: 1f64.to_le_bytes(),
                burn_percent: 0,
            },
            before,
            after: Vec::new(),
            record: Vec::new(),
        };
        out.expect(17, false, 17, n as u32, 17, n as u64);
        out
    }
    fn ctx(&self) -> AddrCtx {
        AddrCtx {
            season: self.before[1].key,
            program: PROGRAM,
        }
    }
    fn input(&self) -> Transition<'_> {
        Transition {
            program: PROGRAM,
            season: self.before[1].key,
            instruction: &self.instruction,
            clock: self.clock,
            rent: self.rent,
            before: &self.before,
            after: &self.after,
            receipt_prefix: b"PS2",
            receipt_body: &self.record,
        }
    }
    fn verify(&self) -> Result<v::Verified, Refusal> {
        v::verify_transition(&self.input())
    }
    // Explicit expected economic outputs. Only the elementary byte writes,
    // supplied balance transfer and literal receipt serialization live here.
    fn expect(
        &mut self,
        paid: u64,
        partial: bool,
        claimed: u64,
        count: u32,
        pool_paid: u64,
        pool_claims: u64,
    ) {
        self.after = self.before.clone();
        self.after[0].lamports += paid;
        self.after[2].lamports -= paid;
        wr_u64(&mut self.after[3].data, DC::CLAIMED, claimed);
        wr_u32(&mut self.after[3].data, DC::COUNT, count);
        wr_u64(&mut self.after[2].data, DP::PAID_TOTAL, pool_paid);
        wr_u64(&mut self.after[2].data, DP::CLAIMS, pool_claims);
        for i in (5..self.after.len()).step_by(2) {
            self.after[i].data[AS::CLAIMED] = 1;
        }
        self.record = vec![1, 61]; // PS2 body version and DEFENCE_CLAIM kind
        self.record.extend_from_slice(&11u32.to_le_bytes());
        self.record.extend_from_slice(&KEEPER);
        self.record.extend_from_slice(&0u32.to_le_bytes());
        self.record.push(self.instruction[8]);
        self.record.extend_from_slice(&paid.to_le_bytes());
        self.record.push(partial as u8);
        self.record.push(0); // no chain links
    }
    fn slot(&mut self, k: usize, edit: impl FnOnce(&mut WideArrivalSlot)) {
        let i = 5 + 2 * k;
        let mut s = WideArrivalSlot::read(&self.before[i].data).unwrap();
        edit(&mut s);
        s.write(&mut self.before[i].data).unwrap();
        self.before[i].key = arrival_slot_address(&self.ctx(), s.dest, s.bell, s.faction, s.i);
    }
    fn next_slot(&mut self) {
        self.before = self.after.clone();
        self.slot(0, |s| {
            s.i += 1;
            s.claimed = false;
        });
    }
}

#[test]
fn six_slots_full_state_and_honest_scope() {
    let c = Case::new(6);
    let r = c.verify().unwrap();
    assert_eq!(r.per_slot_refunds, vec![98_852; 6]); // 101352 cost - 2500
    assert_eq!(
        (
            r.bell,
            r.day,
            r.slots,
            r.region_capped,
            r.day_capped,
            r.paid
        ),
        (11, 0, 6, 17, 17, 17)
    );
    assert!(!r.partial);
    assert!(!r.full_season());
    assert!(!r.authenticated_receipt_replay());
    assert!(!v::FULL_SEASON_REPLAY_SUPPORTED);
    assert!(!v::AUTHENTICATED_RECEIPT_REPLAY_SUPPORTED);
    assert!(!r.not_proven().is_empty());
    assert_eq!(c.after[0].lamports, 117);
    assert_eq!(c.after[2].lamports, FLOOR + 983);
}

#[test]
fn actual_paid_allowance_and_per_call_region_reset_after_refill() {
    let mut c = Case::new(1);
    c.before[2].lamports = FLOOR + 7;
    c.expect(7, true, 7, 1, 7, 1);
    assert_eq!(c.verify().unwrap().day_capped, 17);
    c.next_slot();
    c.before[2].lamports = FLOOR + 100; // external refill supplied in next pre-state
    c.expect(17, false, 24, 2, 24, 2);
    assert_eq!(c.verify().unwrap().paid, 17);
    assert_eq!(rd_u64(&c.after[3].data, DC::CLAIMED), Some(24));
    // These two checks do not assert the intervening refill was authenticated.
}

#[test]
fn shared_day_allowance_pays_seventeen_then_eight() {
    let mut c = Case::new(1);
    c.verify().unwrap();
    c.next_slot();
    c.expect(8, false, 25, 2, 25, 2);
    let r = c.verify().unwrap();
    assert_eq!(
        (r.region_capped, r.day_capped, r.paid, r.partial),
        (17, 8, 8, false)
    );
    // Pre-existing counters can include legacy claims. Their provenance and
    // legacy execution are intentionally not inferred from this wide call.
}

#[test]
fn exhausted_day_and_empty_pool_have_distinct_partial_bits() {
    let mut exhausted = Case::new(1);
    wr_u64(&mut exhausted.before[3].data, DC::CLAIMED, 25);
    exhausted.expect(0, false, 25, 1, 0, 1);
    assert_eq!(exhausted.verify().unwrap().day_capped, 0);
    let mut empty = Case::new(1);
    empty.before[2].lamports = FLOOR;
    empty.expect(0, true, 0, 1, 0, 1);
    assert_eq!(empty.verify().unwrap().day_capped, 17);
    empty.before[2].lamports = FLOOR - 1;
    empty.expect(0, true, 0, 1, 0, 1);
    empty.verify().unwrap();
    assert_eq!(empty.after[5].data[AS::CLAIMED], 1);
    wr_u64(&mut empty.before[2].data, DP::PER_BELL_REGION_CAP, 0);
    empty.expect(0, false, 0, 1, 0, 1);
    empty.verify().unwrap();
}

#[test]
fn created_day_evidence_changes_zero_refund_to_three_hundred() {
    let mut c = Case::new(1);
    // limit 1180 + 720 + 600 = 2500, base refund 0. Created day adds
    // 300 cost units, producing refund 300. Settled is irrelevant.
    c.slot(0, |s| {
        s.ev_limit = 1180;
        s.ev_loaded = 0;
        s.ev_price = 1_000_000;
    });
    assert!(matches!(
        c.verify(),
        Err(Refusal::Ineligible {
            reason: "zero eligible refund",
            ..
        })
    ));
    for flags in [
        AS::FLAG_CREATED_DAY,
        AS::FLAG_CREATED_DAY | AS::FLAG_SETTLED,
    ] {
        c.slot(0, |s| s.flags = flags);
        wr_u64(&mut c.before[2].data, DP::PER_BELL_REGION_CAP, 1000);
        wr_u64(&mut c.before[2].data, DP::PER_KEEPER_DAY_CAP, 1000);
        c.expect(300, false, 300, 1, 300, 1);
        assert_eq!(c.verify().unwrap().per_slot_refunds, vec![300]);
    }
}

#[test]
fn independent_rounding_minimum_tip_and_extreme_evidence() {
    let mut c = Case::new(1);
    // 1001 * 1001 micro / 1e6 rounds UP to 2, not 1. A nonzero minimum
    // priority: ceil(1 * (0 + 1320 + 0) / 1000) = 2, leaving zero.
    wr_u32(&mut c.before[1].data, S::DEFENCE_CAP_MILLI, 2000);
    c.slot(0, |s| {
        s.ev_limit = 1001;
        s.ev_price = 1001;
        s.ev_loaded = 0;
    });
    c.expect(2, false, 2, 1, 2, 1);
    assert_eq!(c.verify().unwrap().per_slot_refunds, vec![2]);
    wr_u32(&mut c.before[1].data, S::MIN_REVEAL_PRIORITY_MILLI, 1);
    assert!(matches!(
        c.verify(),
        Err(Refusal::Ineligible {
            reason: "zero eligible refund",
            ..
        })
    ));
    c.slot(0, |s| s.ev_price = 2000); // ceil(2.002) - ceil(1.320) = 1
    c.expect(1, false, 1, 1, 1, 1);
    assert_eq!(c.verify().unwrap().per_slot_refunds, vec![1]);
    c.slot(0, |s| {
        s.ev_limit = u32::MAX;
        s.ev_loaded = u32::MAX;
        s.ev_price = u64::MAX;
    });
    // fee saturates u64; cap = 2*(4294967295+1320+1048576)-2500,
    // then minimum-tip deduction 2 = 8592031880.
    c.expect(17, false, 17, 1, 17, 1);
    assert_eq!(c.verify().unwrap().per_slot_refunds, vec![8_592_031_880]);
}

#[test]
fn maximum_season_fee_inputs_remain_wide_integer_arithmetic() {
    let mut c = Case::new(1);
    for offset in [
        S::MIN_REVEAL_PRIORITY_MILLI,
        S::REVEAL_CU_LIMIT,
        S::REVEAL_LOADED_LIMIT,
        S::DEFENCE_CAP_MILLI,
    ] {
        wr_u32(&mut c.before[1].data, offset, u32::MAX);
    }
    c.slot(0, |s| {
        s.ev_limit = u32::MAX;
        s.ev_loaded = u32::MAX;
        s.ev_price = u64::MAX;
    });
    assert!(matches!(
        c.verify(),
        Err(Refusal::Ineligible {
            reason: "zero eligible refund",
            ..
        })
    ));
    c.slot(0, |s| s.flags = AS::FLAG_CREATED_DAY);
    c.expect(17, false, 17, 1, 17, 1);
    // Baseline ceil = 18451253334102769. Created-day cap after base
    // deduction = 18451254622590456; their difference is independent
    // of saturated price payment. Both pre-division products exceed u64.
    assert_eq!(c.verify().unwrap().per_slot_refunds, vec![1_288_487_687]);
}

#[test]
fn extra_signer_and_writable_system_privileges_match_handler() {
    let mut c = Case::new(1);
    for account in &mut c.before {
        account.is_signer = true;
    }
    c.before[4].is_writable = true;
    c.expect(17, false, 17, 1, 17, 1);
    c.verify().unwrap();
}

#[test]
fn caps_group_by_bell_and_region_not_individual_slot() {
    let mut c = Case::new(3);
    wr_u64(&mut c.before[2].data, DP::PER_KEEPER_DAY_CAP, 100);
    c.slot(2, |s| s.bell = 9); // another bell gives a fresh 17 allowance
    let s = WideArrivalSlot::read(&c.before[9].data).unwrap();
    let region = wide_region(s.dest.coord());
    c.before[10].key = c.ctx().bell_anchor(9, region);
    wr_u32(&mut c.before[10].data, BA::BELL, 9);
    c.expect(34, false, 34, 3, 34, 3);
    assert_eq!(c.verify().unwrap().region_capped, 34);
    // Same bell but a different full coordinate/region is another group.
    let old_region = wide_region(s.dest.coord());
    let coord = (151..200)
        .map(|p| WideCoord::checked(p, 0).unwrap())
        .find(|coord| wide_region(*coord) != old_region)
        .unwrap();
    c.slot(2, |s| {
        s.bell = 10;
        s.dest = ProvinceKey::new(s.dest.world(), coord);
    });
    c.before[10].key = c.ctx().bell_anchor(10, wide_region(coord));
    wr_u32(&mut c.before[10].data, BA::BELL, 10);
    c.before[10].data[BA::REGION] = wide_region(coord);
    c.expect(34, false, 34, 3, 34, 3);
    assert_eq!(c.verify().unwrap().region_capped, 34);
}

#[test]
fn running_seeded_and_ended_admitted_without_economy_end_gate() {
    for status in [S::STATUS_RUNNING, S::STATUS_SEEDED, S::STATUS_ENDED] {
        let mut c = Case::new(1);
        c.before[1].data[S::STATUS] = status;
        wr_u32(&mut c.before[1].data, S::END_BELL, 10);
        c.expect(17, false, 17, 1, 17, 1);
        c.verify().unwrap();
    }
    for status in [
        S::STATUS_ANNOUNCED,
        S::STATUS_CREATED,
        S::STATUS_CLOSED,
        S::STATUS_ABORTED,
    ] {
        let mut c = Case::new(1);
        c.before[1].data[S::STATUS] = status;
        assert!(matches!(c.verify(), Err(Refusal::Season(_))));
    }
    let mut c = Case::new(1);
    c.clock.unix_timestamp = GENESIS - 1;
    assert!(c.verify().is_err());
    c.clock.unix_timestamp = i64::MAX;
    assert!(c.verify().is_err());
}

#[test]
fn grace_boundary_scheduled_window_lateness_and_clock_slot() {
    let mut c = Case::new(1);
    // Keep current bell 11 while placing the grace endpoint at now.
    let now = c.clock.unix_timestamp;
    wr_i64(&mut c.before[6].data, BA::A, now - 4200);
    assert!(matches!(
        c.verify(),
        Err(Refusal::Ineligible {
            reason: "claim grace closed",
            ..
        })
    ));
    wr_i64(&mut c.before[6].data, BA::A, now - 4200 + 1);
    c.expect(17, false, 17, 1, 17, 1);
    c.verify().unwrap();
    wr_i64(&mut c.before[6].data, BA::A, now - 4200);
    wr_u32(&mut c.before[1].data, S::WINDOW_FROM_BELL, 10);
    wr_u32(&mut c.before[1].data, S::WINDOW_NEXT, 1200);
    c.expect(17, false, 17, 1, 17, 1);
    c.verify().unwrap();
    wr_u32(&mut c.before[1].data, S::WINDOW_FROM_BELL, 11);
    assert!(c.verify().is_err());
    let mut c = Case::new(1);
    c.slot(0, |s| s.ev_slot = 104);
    assert!(c.verify().is_err());
    c.slot(0, |s| s.ev_slot = 99); // saturating subtraction, no wrap
    assert!(c.verify().is_err());
    c.slot(0, |s| s.ev_slot = 105);
    c.clock.slot = 0; // handler uses stored evidence slot, not Clock.slot
    c.expect(17, false, 17, 1, 17, 1);
    c.verify().unwrap();
    wr_i64(&mut c.before[6].data, BA::A, i64::MAX);
    assert!(matches!(c.verify(), Err(Refusal::Overflow("anchor grace"))));
}

#[test]
fn exact_instruction_count_privileges_and_account_order() {
    let base = Case::new(1);
    for byte in 0..base.instruction.len() {
        let mut c = base.clone();
        c.instruction[byte] ^= 0x80;
        assert!(c.verify().is_err(), "instruction byte {byte}");
    }
    let mut c = base.clone();
    c.instruction.push(0);
    assert_eq!(c.verify(), Err(Refusal::Instruction));
    c.instruction = vec![0x70, 0, 0, 0, 0, 1]; // legacy ClaimDefence
    assert_eq!(c.verify(), Err(Refusal::Instruction));
    for i in [0, 1, 2, 3, 5, 6] {
        let mut c = base.clone();
        c.before[i].is_writable ^= true;
        assert!(c.verify().is_err(), "privilege {i}");
    }
    let mut c = base.clone();
    c.before[0].is_signer = false;
    assert!(c.verify().is_err());
    let mut c = base.clone();
    c.before.swap(2, 3);
    assert!(c.verify().is_err());
    let mut c = base.clone();
    c.before.pop();
    assert!(c.verify().is_err());
    let mut c = base;
    c.after.push(c.after[6].clone());
    assert!(c.verify().is_err());
}

#[test]
fn repeated_anchors_require_identical_images_duplicates_refuse() {
    Case::new(2).verify().unwrap();
    let mut c = Case::new(2);
    c.before[7] = c.before[5].clone();
    assert!(matches!(c.verify(), Err(Refusal::Accounts(_))));
    let mut c = Case::new(2);
    c.before[8].lamports += 1;
    assert!(matches!(c.verify(), Err(Refusal::Accounts(_))));
    let mut c = Case::new(2);
    c.after[8].data[BA::RSV] ^= 1;
    assert!(matches!(c.verify(), Err(Refusal::Accounts(_))));
    let mut c = Case::new(1);
    c.before[0].key = c.before[2].key;
    assert!(matches!(c.verify(), Err(Refusal::Accounts(_))));
}

#[test]
fn canonical_addresses_owners_header_and_season_pins() {
    let base = Case::new(1);
    for index in [0, 1, 2, 3, 4, 5, 6] {
        let mut c = base.clone();
        c.before[index].key[0] ^= 1;
        assert!(c.verify().is_err(), "address {index}");
    }
    for index in [1, 2, 3, 5, 6] {
        let mut c = base.clone();
        c.before[index].owner[0] ^= 1;
        assert!(c.verify().is_err(), "owner {index}");
        for offset in [0, 8] {
            let mut c = base.clone();
            c.before[index].data[offset] ^= 1;
            assert!(c.verify().is_err(), "header {index}/{offset}");
        }
    }
    for offset in [S::RULESET_HASH, S::PROGRAM_VERSION, S::BUMP] {
        let mut c = base.clone();
        c.before[1].data[offset] ^= 1;
        assert!(c.verify().is_err());
    }
    let mut c = base.clone();
    wr_u16(
        &mut c.before[1].data,
        S::PROGRAM_VERSION,
        PROGRAM_VERSION_S1 | 0xc000,
    );
    c.expect(17, false, 17, 1, 17, 1);
    c.verify().unwrap();
    for index in [1, 2, 3, 6] {
        let mut c = base.clone();
        c.before[index].data.push(0xa5); // handler accepts minimum-size legacy accounts
        c.expect(17, false, 17, 1, 17, 1);
        c.verify().unwrap();
        c.before[index].data.truncate(15);
        assert!(c.verify().is_err());
    }
}

#[test]
fn wrong_day_claim_beneficiary_world_and_anchor_refuse() {
    for (index, offset) in [
        (3, DC::DAY),
        (3, DC::BENEFICIARY),
        (6, BA::BELL),
        (6, BA::REGION),
    ] {
        let mut c = Case::new(1);
        c.before[index].data[offset] ^= 1;
        assert!(c.verify().is_err());
    }
    let mut c = Case::new(1);
    c.slot(0, |s| s.beneficiary = [0x66; 32]);
    assert!(c.verify().is_err());
    let mut c = Case::new(1);
    c.slot(0, |s| s.claimed = true);
    assert!(c.verify().is_err());
    let mut c = Case::new(1);
    let other = WorldId::new([0x77; 32]).unwrap();
    c.slot(0, |s| {
        s.dest = ProvinceKey::new(other, s.dest.coord());
        s.host = WideHostRef::new(s.dest, 0, 2, 1).unwrap();
    });
    assert!(matches!(
        c.verify(),
        Err(Refusal::Ineligible {
            reason: "slot Season or world",
            ..
        })
    ));
    let mut c = Case::new(1);
    c.clock.unix_timestamp = GENESIS + 144 * 600;
    assert_eq!(c.verify(), Err(Refusal::Instruction));
}

#[test]
fn landing_day_is_current_day_not_the_slots_day() {
    let mut c = Case::new(1);
    c.clock.unix_timestamp = GENESIS + 144 * 600;
    c.instruction[4] = 1;
    c.before[3].key = c.ctx().of(&defence_claim_seed(&keeper_tag8(&KEEPER), 1));
    wr_u32(&mut c.before[3].data, DC::DAY, 1);
    c.slot(0, |s| s.bell = 143);
    let s = WideArrivalSlot::read(&c.before[5].data).unwrap();
    c.before[6].key = c.ctx().bell_anchor(143, wide_region(s.dest.coord()));
    wr_u32(&mut c.before[6].data, BA::BELL, 143);
    wr_i64(&mut c.before[6].data, BA::A, GENESIS + 143 * 600);
    c.expect(17, false, 17, 1, 17, 1);
    c.record[2..6].copy_from_slice(&144u32.to_le_bytes());
    c.record[38..42].copy_from_slice(&1u32.to_le_bytes());
    let r = c.verify().unwrap();
    assert_eq!((r.bell, r.day), (144, 1));
}

#[test]
fn absent_claim_live_anchor_and_legacy_or_malformed_slot_bytes_refuse() {
    let mut c = Case::new(1);
    c.before[3].owner = [0; 32];
    c.before[3].data.clear();
    assert_eq!(
        c.verify(),
        Err(Refusal::Unsupported(
            "absent claim requires allocation/System CPI"
        ))
    );
    let mut c = Case::new(1);
    c.before[6].owner = [0; 32];
    c.before[6].data.clear();
    assert!(c.verify().is_err());
    let mut c = Case::new(1);
    c.before[5].data = header(*b"PSF1ARSL", 160);
    assert!(c.verify().is_err());
    for (offset, byte) in [
        (AS::CLAIMED, 2),
        (AS::FLAGS, 128),
        (AS::RSV, 1),
        (AS::FACTION, 6),
        (AS::I, 4),
        (AS::FAMILY_VERSION, 255),
        (AS::TILE, 255),
    ] {
        let mut c = Case::new(1);
        c.before[5].data[offset] = byte;
        assert!(c.verify().is_err(), "slot encoding {offset}");
    }
}

#[test]
fn counters_and_keeper_overflow_fail_closed() {
    let mut c = Case::new(1);
    wr_u32(&mut c.before[3].data, DC::COUNT, u32::MAX);
    assert_eq!(c.verify(), Err(Refusal::Overflow("claim count")));
    for (offset, reason) in [
        (DP::PAID_TOTAL, "pool paid total"),
        (DP::CLAIMS, "pool claims"),
    ] {
        let mut c = Case::new(1);
        wr_u64(&mut c.before[2].data, offset, u64::MAX);
        assert_eq!(c.verify(), Err(Refusal::Overflow(reason)));
    }
    let mut c = Case::new(1);
    c.before[0].lamports = u64::MAX;
    assert_eq!(c.verify(), Err(Refusal::Overflow("keeper balance")));
    // Claimed+paid cannot overflow under a u64 day cap; an already-max
    // claim saturates remaining allowance to zero rather than overflowing.
    let mut c = Case::new(1);
    wr_u64(&mut c.before[3].data, DC::CLAIMED, u64::MAX);
    c.expect(0, false, u64::MAX, 1, 0, 1);
    c.verify().unwrap();
}

#[test]
fn supplied_rent_floor_thresholds_and_explicit_subset() {
    let mut c = Case::new(1);
    c.rent.exemption_threshold = 2f64.to_le_bytes();
    c.before[2].lamports = 768 + 7;
    c.expect(7, true, 7, 1, 7, 1);
    c.verify().unwrap();
    c.rent.lamports_per_byte = u64::MAX;
    assert_eq!(c.verify(), Err(Refusal::Overflow("Rent")));
    c.rent.lamports_per_byte = 1;
    c.rent.exemption_threshold = 1.5f64.to_le_bytes();
    assert_eq!(
        c.verify(),
        Err(Refusal::Unsupported("nonstandard Rent threshold"))
    );
    let mut c = Case::new(1);
    c.rent.lamports_per_byte = 0;
    c.before[2].lamports = 7;
    c.expect(7, true, 7, 1, 7, 1);
    c.verify().unwrap();
}

#[test]
fn maximum_rent_rates_are_admitted_but_next_rate_refuses() {
    for (threshold, rate, floor) in [
        (1f64, 1_759_197_129_867u64, 675_531_697_868_928u64),
        (2f64, 879_598_564_933, 675_531_697_868_544),
    ] {
        let mut c = Case::new(1);
        c.rent.exemption_threshold = threshold.to_le_bytes();
        c.rent.lamports_per_byte = rate;
        c.before[2].lamports = floor + 17;
        c.expect(17, false, 17, 1, 17, 1);
        c.verify().unwrap();
        c.rent.lamports_per_byte = rate + 1;
        assert_eq!(c.verify(), Err(Refusal::Overflow("Rent")));
    }
}

#[test]
fn every_post_byte_balance_and_metadata_change_refuses() {
    let base = Case::new(1);
    base.verify().unwrap();
    for index in 0..base.after.len() {
        for byte in 0..base.after[index].data.len() {
            let mut c = base.clone();
            c.after[index].data[byte] ^= 1;
            assert!(c.verify().is_err(), "post account {index}, byte {byte}");
        }
        for field in 0..8 {
            let mut c = base.clone();
            match field {
                0 => c.after[index].lamports ^= 1,
                1 => c.after[index].key[0] ^= 1,
                2 => c.after[index].owner[0] ^= 1,
                3 => c.after[index].executable ^= true,
                4 => c.after[index].rent_epoch ^= 1,
                5 => c.after[index].is_signer ^= true,
                6 => c.after[index].is_writable ^= true,
                _ => c.after[index].data.push(0),
            }
            assert!(
                c.verify().is_err(),
                "post account {index}, metadata {field}"
            );
        }
    }
}

#[test]
fn every_receipt_byte_trailing_prefix_and_nonzero_tail_refuses() {
    let base = Case::new(1);
    for byte in 0..base.record.len() {
        let mut c = base.clone();
        c.record[byte] ^= 1;
        assert_eq!(c.verify(), Err(Refusal::Receipt), "receipt byte {byte}");
    }
    let mut c = base.clone();
    c.record.push(0);
    assert_eq!(c.verify(), Err(Refusal::Receipt));
    let mut c = base.clone();
    c.record.pop();
    assert_eq!(c.verify(), Err(Refusal::Receipt));
    let mut c = base.clone();
    *c.record.last_mut().unwrap() = 1;
    c.record.push(1); // legal Season entity but forbidden for this zero-link record
    c.record.extend_from_slice(&[0; 40]);
    assert_eq!(c.verify(), Err(Refusal::Receipt));
    let mut input = base.input();
    input.receipt_prefix = b"PSW1";
    assert_eq!(v::verify_transition(&input), Err(Refusal::Receipt));
}

#[test]
fn receipt_does_not_authenticate_slots_or_timestamp() {
    let first = Case::new(1);
    let mut other = first.clone();
    other.slot(0, |s| s.i = 1);
    other.clock.unix_timestamp += 1; // same bell, another timestamp
    other.expect(17, false, 17, 1, 17, 1);
    assert_eq!(first.record, other.record);
    first.verify().unwrap();
    other.verify().unwrap();
    assert_ne!(first.before[5].key, other.before[5].key);
    assert!(!other.verify().unwrap().authenticated_receipt_replay());
}
